import{_ as d,o as e,c as o,ag as r}from"./chunks/framework.B7PviQjB.js";const f=JSON.parse('{"title":"Keyboard shortcuts","description":"Every keyboard shortcut in the Docs editor, for Mac and for Windows and Linux.","frontmatter":{"title":"Keyboard shortcuts","description":"Every keyboard shortcut in the Docs editor, for Mac and for Windows and Linux.","type":"reference"},"headers":[],"relativePath":"docs-editor/keyboard-shortcuts.md","filePath":"docs-editor/keyboard-shortcuts.md"}'),c={name:"docs-editor/keyboard-shortcuts.md"};function a(i,t,l,n,h,s){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h1><p>Keyboard shortcuts for writing and formatting in a doc.</p><p>Mac keys come first, then Windows and Linux: <code>⌘+B</code> / <code>Ctrl+B</code>. On Mac, <code>Option</code> is the key labeled ⌥.</p><p>To see a shorter list in the app, press <code>⌘+/</code> / <code>Ctrl+/</code> in a doc. Press <code>Escape</code> to close it. This page also lists keys the in-app list leaves out, such as selection, the Mac <code>⌘+arrow</code> keys, and table keys.</p><p>On a phone, shortcuts work only with a hardware keyboard. Find, replace, and the shortcut list have no button, so they need one.</p><h2 id="most-used" tabindex="-1">Most used <a class="header-anchor" href="#most-used" aria-label="Permalink to &quot;Most used&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>Bold</td><td><code>⌘+B</code> / <code>Ctrl+B</code></td></tr><tr><td>Italic</td><td><code>⌘+I</code> / <code>Ctrl+I</code></td></tr><tr><td>Underline</td><td><code>⌘+U</code> / <code>Ctrl+U</code></td></tr><tr><td>Insert or edit a link</td><td><code>⌘+K</code> / <code>Ctrl+K</code></td></tr><tr><td>Undo</td><td><code>⌘+Z</code> / <code>Ctrl+Z</code></td></tr><tr><td>Redo</td><td><code>⌘+Shift+Z</code> or <code>⌘+Y</code> / <code>Ctrl+Y</code> or <code>Ctrl+Shift+Z</code></td></tr><tr><td>Paste without formatting</td><td><code>⌘+Shift+V</code> / <code>Ctrl+Shift+V</code></td></tr><tr><td>Find</td><td><code>⌘+F</code> / <code>Ctrl+F</code></td></tr><tr><td>Insert comment on the selection</td><td><code>⌘+Option+M</code> / <code>Ctrl+Alt+M</code></td></tr></tbody></table><h2 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>Move by character or line</td><td><code>←</code> <code>→</code> <code>↑</code> <code>↓</code></td></tr><tr><td>Move by word</td><td><code>Option+←</code> or <code>Option+→</code> / <code>Ctrl+←</code> or <code>Ctrl+→</code></td></tr><tr><td>Go to start of line</td><td><code>⌘+←</code> or <code>Home</code> / <code>Home</code></td></tr><tr><td>Go to end of line</td><td><code>⌘+→</code> or <code>End</code> / <code>End</code></td></tr><tr><td>Go to start of document</td><td><code>⌘+↑</code> or <code>⌘+Home</code> / <code>Ctrl+Home</code></td></tr><tr><td>Go to end of document</td><td><code>⌘+↓</code> or <code>⌘+End</code> / <code>Ctrl+End</code></td></tr></tbody></table><h2 id="selection" tabindex="-1">Selection <a class="header-anchor" href="#selection" aria-label="Permalink to &quot;Selection&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>Select all</td><td><code>⌘+A</code> / <code>Ctrl+A</code></td></tr><tr><td>Extend the selection</td><td><code>Shift</code> with any navigation key above</td></tr><tr><td>Select a word</td><td>Double-click</td></tr><tr><td>Select a paragraph</td><td>Triple-click</td></tr></tbody></table><h2 id="editing" tabindex="-1">Editing <a class="header-anchor" href="#editing" aria-label="Permalink to &quot;Editing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>New paragraph</td><td><code>Enter</code></td></tr><tr><td>Page break</td><td><code>⌘+Enter</code> / <code>Ctrl+Enter</code></td></tr><tr><td>Delete previous word</td><td><code>Option+Backspace</code> / <code>Ctrl+Backspace</code></td></tr><tr><td>Delete next word</td><td><code>Option+Delete</code> / <code>Ctrl+Delete</code></td></tr><tr><td>Delete to start of line (Mac only)</td><td><code>⌘+Backspace</code></td></tr><tr><td>Copy</td><td><code>⌘+C</code> / <code>Ctrl+C</code></td></tr><tr><td>Cut</td><td><code>⌘+X</code> / <code>Ctrl+X</code></td></tr><tr><td>Paste</td><td><code>⌘+V</code> / <code>Ctrl+V</code></td></tr><tr><td>Paste without formatting</td><td><code>⌘+Shift+V</code> / <code>Ctrl+Shift+V</code></td></tr><tr><td>Copy formatting</td><td><code>⌘+Shift+C</code> / <code>Ctrl+Shift+C</code></td></tr><tr><td>Paste formatting (repeatable)</td><td><code>⌘+Option+V</code> / <code>Ctrl+Alt+V</code></td></tr><tr><td>Undo</td><td><code>⌘+Z</code> / <code>Ctrl+Z</code></td></tr><tr><td>Redo</td><td><code>⌘+Shift+Z</code> or <code>⌘+Y</code> / <code>Ctrl+Y</code> or <code>Ctrl+Shift+Z</code></td></tr></tbody></table><h2 id="formatting" tabindex="-1">Formatting <a class="header-anchor" href="#formatting" aria-label="Permalink to &quot;Formatting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>Bold</td><td><code>⌘+B</code> / <code>Ctrl+B</code></td></tr><tr><td>Italic</td><td><code>⌘+I</code> / <code>Ctrl+I</code></td></tr><tr><td>Underline</td><td><code>⌘+U</code> / <code>Ctrl+U</code></td></tr><tr><td>Strikethrough</td><td><code>⌘+Shift+X</code> / <code>Ctrl+Shift+X</code></td></tr><tr><td>Superscript</td><td><code>⌘+.</code> / <code>Ctrl+.</code></td></tr><tr><td>Subscript</td><td><code>⌘+,</code> / <code>Ctrl+,</code></td></tr><tr><td>Insert or edit a link</td><td><code>⌘+K</code> / <code>Ctrl+K</code></td></tr><tr><td>Clear formatting</td><td><code>⌘+\\</code> / <code>Ctrl+\\</code></td></tr><tr><td>Heading 1 to Heading 6</td><td><code>⌘+Option+1</code> to <code>⌘+Option+6</code> / <code>Ctrl+Alt+1</code> to <code>Ctrl+Alt+6</code></td></tr><tr><td>Normal text</td><td><code>⌘+Option+0</code> / <code>Ctrl+Alt+0</code></td></tr><tr><td>Align left</td><td><code>⌘+Shift+L</code> / <code>Ctrl+Shift+L</code></td></tr><tr><td>Align center</td><td><code>⌘+Shift+E</code> / <code>Ctrl+Shift+E</code></td></tr><tr><td>Align right</td><td><code>⌘+Shift+R</code> / <code>Ctrl+Shift+R</code></td></tr><tr><td>Justify</td><td><code>⌘+Shift+J</code> / <code>Ctrl+Shift+J</code></td></tr><tr><td>Numbered list</td><td><code>⌘+Shift+7</code> / <code>Ctrl+Shift+7</code></td></tr><tr><td>Bulleted list</td><td><code>⌘+Shift+8</code> / <code>Ctrl+Shift+8</code></td></tr><tr><td>Increase indent</td><td><code>⌘+]</code> / <code>Ctrl+]</code></td></tr><tr><td>Decrease indent</td><td><code>⌘+[</code> / <code>Ctrl+[</code></td></tr></tbody></table><p>Pressing the shortcut for the heading a line already has turns it back into normal text.</p><h3 id="what-tab-does" tabindex="-1">What <code>Tab</code> does <a class="header-anchor" href="#what-tab-does" aria-label="Permalink to &quot;What `Tab` does&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Where the cursor is</th><th><code>Tab</code></th><th><code>Shift+Tab</code></th></tr></thead><tbody><tr><td>In a table cell</td><td>Next cell</td><td>Previous cell</td></tr><tr><td>In the last cell of a table</td><td>Adds a row</td><td>Previous cell</td></tr><tr><td>In a list item</td><td>Nests it one level deeper</td><td>Moves it one level out</td></tr><tr><td>In any other paragraph</td><td>Nothing</td><td>Nothing</td></tr></tbody></table><p>To indent a plain paragraph, use <code>⌘+]</code> / <code>Ctrl+]</code>.</p><h2 id="objects" tabindex="-1">Objects <a class="header-anchor" href="#objects" aria-label="Permalink to &quot;Objects&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>Delete a selected image</td><td><code>Delete</code> or <code>Backspace</code></td></tr><tr><td>Copy or cut a selected image</td><td><code>⌘+C</code> or <code>⌘+X</code> / <code>Ctrl+C</code> or <code>Ctrl+X</code></td></tr><tr><td>Deselect an image</td><td><code>Escape</code></td></tr><tr><td>Resize an image freely (while dragging a corner)</td><td>Hold <code>Shift</code></td></tr><tr><td>Leave a header or footer</td><td><code>Escape</code></td></tr></tbody></table><h2 id="view" tabindex="-1">View <a class="header-anchor" href="#view" aria-label="Permalink to &quot;View&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>Find</td><td><code>⌘+F</code> / <code>Ctrl+F</code></td></tr><tr><td>Find and replace</td><td><code>⌘+H</code> / <code>Ctrl+H</code></td></tr><tr><td>Next or previous match (in the find bar)</td><td><code>Enter</code> or <code>Shift+Enter</code></td></tr><tr><td>Close the find bar</td><td><code>Escape</code></td></tr><tr><td>Insert comment on the selection</td><td><code>⌘+Option+M</code> / <code>Ctrl+Alt+M</code></td></tr><tr><td>Show or hide the comments panel</td><td><code>⌘+Option+Shift+M</code> / <code>Ctrl+Alt+Shift+M</code></td></tr><tr><td>Show keyboard shortcuts</td><td><code>⌘+/</code> / <code>Ctrl+/</code></td></tr></tbody></table><h2 id="in-a-view-only-document" tabindex="-1">In a view-only document <a class="header-anchor" href="#in-a-view-only-document" aria-label="Permalink to &quot;In a view-only document&quot;">​</a></h2><p>When you can only view a document, for example through a viewer share link, these keys still work:</p><ul><li>Arrow keys, <code>Home</code>, and <code>End</code>, with or without <code>Shift</code></li><li><code>⌘+A</code> / <code>Ctrl+A</code> to select all, and <code>⌘+C</code> / <code>Ctrl+C</code> to copy</li><li><code>⌘+F</code> / <code>Ctrl+F</code> to find (there is no replace)</li><li><code>⌘+/</code> / <code>Ctrl+/</code> to show the shortcut list</li><li><code>⌘+Option+Shift+M</code> / <code>Ctrl+Alt+Shift+M</code> to show or hide comments, which you can read but not reply to</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/docs-editor/format-text.html">Format text</a> for the toolbar controls behind these shortcuts.</li><li><a href="/docs/docs-editor/lists-and-indents.html">Lists and indents</a> for nesting with <code>Tab</code>.</li><li><a href="/docs/docs-editor/find-and-spelling.html">Find and spelling</a> for the find bar.</li></ul>',28)])])}const u=d(c,[["render",a]]);export{f as __pageData,u as default};
